SELECT
*
FROM
mp_devops_load


        and pk = #{param.pk}


        and tool_name like concat('%', #{param.toolName}, '%')


        and action_type = #{param.actionType}


        and run_table = #{param.runTable}


        and source = #{param.source}


        and control_type = #{param.controlType}


order by create_time desc

    limit #{param.offset}, #{param.pageSize}

SELECT
*
FROM
mp_devops_load_scene_result_log


        and pk = #{param.pk}


        and pk in

            #{item}



        and scene_id = #{param.sceneId}


        and id = #{param.id}


        and id in

            #{item}



        and tool_name like concat('%', #{param.toolName}, '%')


        and action_type = #{param.actionType}


        and run_table = #{param.runTable}


        and source = #{param.source}


        and control_type = #{param.controlType}


        and control_type = #{param.controlType}


        and create_time >= #{param.beginTime}


        and create_time <= #{param.overTime}



    limit #{param.offset}, #{param.pageSize}

SELECT * FROM mp_devops_load
and pk in
#{item}

SELECT log.id as tool_id, log.tool_name, DATE_FORMAT(log.create_time, '%Y-%m-%d %H:%i:%S') AS create_time FROM mp_devops_load_scene_result_log log
and log.id in
#{item}

SELECT scene_element FROM mp_sceneplugincloud_scene_element
and image_type = 'load'
and scene = #{sceneId}
